    total_seconds = weeks * 7 * 86400 + days * 86400 + hours * 3600 + minutes * 60 + seconds

    return total_seconds


def is_valid_number(s: str) -> bool:
    """Check if string is a valid non-negative integer or decimal number (ASCII digits only)"""
    if not s:
        return False

    # Count dots and commas
    decimal_count = s.count('.') + s.count(',')
    if decimal_count > 1:
        return False

    if decimal_count == 1:
        # Has decimal - must have digits on both sides
        parts = s.replace(',', '.').split('.')
        return all(part and all(c in '0123456789' for c in part) for part in parts)
    else:
        # No decimal - just digits
        return all(c in '0123456789' for c in s)


def parse_number(s: str) -> float:
    """Parse a number string, handling both '.' and ',' as decimal separator"""
    s = s.replace(',', '.')
    return float(s)

